from concurrent.futures import ThreadPoolExecutor

import pytest


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Return parity (0 or 1) of each element of xs, computed in parallel
    with a thread pool. Results are in input order regardless of the
    number of workers."""
    import concurrent.futures

    with concurrent.futures.ThreadPoolExecutor() as pool:
        return list(pool.map(parity, xs))


def test_parities_basic() -> None:
    assert parities([1, 2, 3, 4]) == [1, 0, 1, 0]


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_negative() -> None:
    assert parities([-1, -2, -3]) == [1, 0, 1]


def test_parities_large_values() -> None:
    assert parities([2**100, 2**100 + 1]) == [0, 1]


def test_parities_order_preserved_large_input() -> None:
    xs = list(range(10_000))
    assert parities(xs) == [x % 2 for x in xs]


def test_parities_does_not_mutate_input() -> None:
    xs = [5, 6, 7]
    parities(xs)
    assert xs == [5, 6, 7]


def test_parities_returns_new_list() -> None:
    xs = [0, 1]
    out = parities(xs)
    assert out is not xs


def test_parities_order_independent_of_worker_count(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    xs = [7, 8, 9, 10, 11, 12, 13] * 50
    expected = [x % 2 for x in xs]
    real = ThreadPoolExecutor
    for workers in (1, 2, 3, 8, 32):

        def factory(*args: object, _w: int = workers, **kwargs: object) -> ThreadPoolExecutor:
            return real(max_workers=_w)

        monkeypatch.setattr(
            "concurrent.futures.ThreadPoolExecutor", factory
        )
        assert parities(xs) == expected

